local BY,CH,FL=string.byte,string.char,math.floor
local function dec(s)
    local out,n,acc,j={},0,0,0
    for i=1,#s do
        local v=M[BY(s,i)]
        if v then
            acc=acc*64+v
            n=n+6
            if n>7 then
                n=n-8
                local p=2^n
                local c=FL(acc/p)%256
                acc=acc%p
                j=j+1
                out[j]=CH((c-KB[(j-1)%KL+1])%256)
            end
        end
    end
    return table.concat(out)
end
if type(loadstring)~="function" then error("BSY: this executor has no loadstring support",0) end
local src=dec(P)
local fn,err=loadstring(src,"BSY")
if not fn then error("BSY: payload rejected: "..tostring(err),0) end
pcall(function()
    local info=debug.info(1,"s")
    if type(info)=="table" and type(info.source)=="string" then getgenv().BSYSourcePath=info.source end
end)
return fn()
